use anyhow :: { Context , Result } ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use std :: io :: { BufRead , BufReader } ; use log :: info ; # [doc = " Fast count directories in a path"] fn fast_count_directories (path : & Path) -> Result < usize > { if ! path . exists () { return Ok (0) ; } let mut count = 0 ; for entry in fs :: read_dir (path) ? { if let Ok (entry) = entry { if entry . path () . is_dir () { count += 1 ; } } } Ok (count) }